ShouldIgnoreDeoxysForm.body:
switch (caseId)
    {
    case 0:
    default:
        return FALSE;
    case 1:  
        if (!(gBattleTypeFlags & BATTLE_TYPE_MULTI))
            return FALSE;
        if (!gMain.inBattle)
            return FALSE;
        if (gLinkPlayers[GetMultiplayerId()].id == battler)
            return FALSE;
        break;
    case 2:
        break;
    case 3:  
        if (!(gBattleTypeFlags & BATTLE_TYPE_MULTI))
            return FALSE;
        if (!gMain.inBattle)
            return FALSE;
        if (battler == 1 || battler == 4 || battler == 5)
            return TRUE;
        return FALSE;
    case 4:
        break;
    case 5:  
        if (gBattleTypeFlags & BATTLE_TYPE_LINK)
        {
            if (!gMain.inBattle)
                return FALSE;
            if (gBattleTypeFlags & BATTLE_TYPE_MULTI)
            {
                if (gLinkPlayers[GetMultiplayerId()].id == battler)
                    return FALSE;
            }
            else
            {
                if (GetBattlerSide(battler) == B_SIDE_PLAYER)
                    return FALSE;
            }
        }
        else
        {
            if (!gMain.inBattle)
                return FALSE;
            if (GetBattlerSide(battler) == B_SIDE_PLAYER)
                return FALSE;
        }
        break;
    }

    return TRUE;

